#include <bits/stdc++.h>using namespace std;using ll = long long; int main() {     ios::sync_with_stdio(false);    cin.tie(nullptr);     int T;    cin >> T;     while(T--) {         int n;        ll k;        cin >> n >> k;         // max heap        // first = remainder priority        // second = -index (for smaller index priority)        priority_queue<pair<ll,int>> pq;         for(int i = 1; i <= n; i++) {             ll a;            cin >> a;             // remainder determines death order            ll rem = a % k;             if(rem == 0)                rem = k;             pq.push({rem, -i});        }         // print order monsters die        while(!pq.empty()) {             auto [rem, idx] = pq.top();            pq.pop();             cout << -idx << " ";        }         cout << "\n";    }}